// Burned-in captions: short word chunks from captions_data.ts (generated by scripts/captions.py from words.json), the
// spoken word lit warm yellow, each chunk pops in. Bold white type with a dark plum outline (the character ink colour)
// in the lower third, above the platform UI zone. Sizes are set at 1080x1920 and scale with the output height.
// Off for test stills / look checks with inputProps `{ captions: false }`.
import React from "react";
import { AbsoluteFill, getInputProps, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import { CAPTIONS } from "./captions_data";

const FONT = '"Arial Rounded MT Bold", "Arial Black", "Segoe UI Black", Arial, sans-serif';
const INK = "#241726", HOT = "#ffd84a", WHITE = "#fffaf0";

export const captionsOn = () => (getInputProps() as { captions?: boolean }).captions !== false;
/** the caption band (1080x1920 coordinates): faces and hero props must stay out of it */
export const BAND: [number, number] = [1280, 1520];
/** look-check stills only: inputProps `{ band: true }` draws the band and logs "[band]" warnings (world.ts) */
export const bandOn = () => !!(getInputProps() as { band?: boolean }).band;
export const BandGuide: React.FC = () => (
  <AbsoluteFill style={{ pointerEvents: "none" }}>
    <div style={{ position: "absolute", left: 0, right: 0, top: `${(100 * BAND[0]) / 1920}%`, height: `${(100 * (BAND[1] - BAND[0])) / 1920}%`,
      background: "rgba(255,0,170,0.16)", borderTop: "3px dashed rgba(255,0,170,0.9)", borderBottom: "3px dashed rgba(255,0,170,0.9)" }} />
  </AbsoluteFill>
);

export const Captions: React.FC = () => {
  const f = useCurrentFrame();
  const { height } = useVideoConfig();
  const u = height / 1920;
  const c = CAPTIONS.find((x) => f >= x.a && f < x.b);
  if (!c) return null;
  const t = f - c.a;
  const pop = interpolate(t, [0, 3, 6], [0.82, 1.06, 1], { extrapolateRight: "clamp" });
  const e = Math.min(2, (c.b - c.a) / 3), g = Math.min(3, (c.b - c.a) / 3); // short chunks: keep the range strictly increasing
  const fade = interpolate(f, [c.a, c.a + e, c.b - g, c.b], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <div style={{
        position: "absolute", left: 70 * u, right: 70 * u, top: 1300 * u, display: "flex", flexWrap: "wrap",
        justifyContent: "center", gap: `0 ${22 * u}px`, transform: `scale(${pop})`, opacity: fade,
        fontFamily: FONT, fontSize: 96 * u, lineHeight: 1.12, fontWeight: 900, letterSpacing: 1 * u, textAlign: "center",
      }}>
        {c.words.map((w, i) => {
          const live = f >= w.a && (f < w.b || i === c.words.length - 1 || f < c.words[i + 1].a);
          return (
            <span key={i} style={{
              color: live ? HOT : WHITE,
              WebkitTextStroke: `${14 * u}px ${INK}`, paintOrder: "stroke fill",
              textShadow: `0 ${7 * u}px 0 ${INK}, 0 ${10 * u}px ${18 * u}px rgba(20,10,30,0.45)`,
              transform: live ? `translateY(${-4 * u}px)` : undefined, display: "inline-block",
            }}>{w.w}</span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};
